use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let bytes = input.as_array().unwrap();
    let mut result = String::new();
    for byte in bytes {
        let num = byte.as_i64().unwrap() as u32;
        let hex = format!("{:x}", num);
        result.push_str(&hex);
        result.push_str("-");
    }
    Value::from(result)
}
